    function run(uint256 depositAmount) public payable {
        require(depositAmount > 0, "deposit amount must be nonzero");
        require(address(this).balance >= depositAmount, "insufficient test contract balance");

        uint256 beforeC = address(c).balance;
        uint256 beforeTest = address(this).balance;

        c.deposit{value: depositAmount}();

        uint256 afterDepositC = address(c).balance;
        require(afterDepositC == beforeC + depositAmount, "deposit must increase c balance by exactly depositAmount");

